UPDATE knowledge_base
SET name = #{name},
    description = #{description}
WHERE id = #{id}
  AND owner_user_id = #{ownerUserId}
  AND deleted_at IS NULL

UPDATE knowledge_base
SET deleted_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND owner_user_id = #{ownerUserId}
  AND deleted_at IS NULL
